// INHERITANCE (IS-A): bound to a parent at compile time
class Engine { void start() { System.out.println("vroom"); } }
class WrongCar extends Engine { }       // a Car IS-A Engine? No -> wrong model

// COMPOSITION (HAS-A): a Car holds an Engine and delegates
class Car {
    private final Engine engine;        // HAS-A relationship
    Car(Engine engine) { this.engine = engine; }  // injected -> swappable
    void start() { engine.start(); }    // delegate to the part
}

// Composition lets you swap the part without touching Car:
Car petrol = new Car(new Engine());
// Car electric = new Car(new ElectricEngine()); // same Car, new behavior
```
Inheritance reuses by subclassing (tight); composition reuses by delegation (loose and flexible).

// Composition approach with dependency injection
public interface NotificationService {
    void send(String message, String recipient);
}

@Service
public class OrderService {
    private final NotificationService notificationService; // composition - has-a
    private final OrderRepository orderRepository;

    public OrderService(NotificationService notificationService, 
                       OrderRepository orderRepository) {
        this.notificationService = notificationService; // injected at runtime
        this.orderRepository = orderRepository;
    }

    public void placeOrder(Order order) {
        orderRepository.save(order);
        notificationService.send("Order placed", order.customerEmail());
        // can swap EmailNotification for SmsNotification at runtime
        // can inject mock NotificationService in tests
    }
}

// In production: inject EmailNotificationService
// In tests: inject mock that verifies send() was called
// No inheritance hierarchy, no tight coupling

// Original parent implementation
public class AbstractRepository {
    protected List<String> items = new ArrayList<>();

    public void add(String item) {
        items.add(item); // direct add
    }

    public int size() {
        return items.size();
    }
}

// Subclass overrides add to track count
public class CountingRepository extends AbstractRepository {
    private int addCount = 0;

    @Override
    public void add(String item) {
        super.add(item);
        addCount++; // tracks how many times add was called
    }

    public int getAddCount() { return addCount; }
}

// Parent refactored - seems safe, public API unchanged
public class AbstractRepository {
    protected List<String> items = new ArrayList<>();

    public void add(String item) {
        addInternal(item); // now delegates to helper
    }

    protected void addInternal(String item) {
        items.add(item); // actual add logic moved here
    }
}

// CountingRepository is now BROKEN - addCount is always zero
// because add() calls addInternal(), which doesn't increment the counter
// The parent's public contract didn't change, but subclass broke

